
import pandas as pd

# Read the CSV generated by your existing program
study = pd.read_csv("western_avenue_businesses.csv")
analysis = pd.read_csv("western_avenue_section_counts.csv")

print("\n--- Geographic check ---")

print("Total businesses:", len(study))

print(
    "Latitude range:",
    study["latitude"].min(),
    "to",
    study["latitude"].max()
)

print(
    "Longitude range:",
    study["longitude"].min(),
    "to",
    study["longitude"].max()
)

print("\n--- First 10 business locations ---")

columns = [
    "business_name",
    "street_address",
    "latitude",
    "longitude"
]

print(study[columns].head(10).to_string(index=False))

print("\n--- Business counts by section ---")
print(analysis.to_string(index=False))

print("\nCheck completed!")
